        raise ValueError("malformed duration")

    parts = re.findall(r"([0-9]+)([hms])", s)
    seen = set()
    multipliers = {"h": 3600, "m": 60, "s": 1}
    total = 0

    for number, unit in parts:
        if unit in seen:
            raise ValueError("repeated unit")
        seen.add(unit)
        total += int(number) * multipliers[unit]

    return total
